const {test}=require('node:test');const assert=require('node:assert/strict');const {readCentralIdentity}=require('./central-identity.cjs');
const good={user:{userId:'official-user',realName:'Verified Name',jobTitle:'经理'},access:{master_access:true,allowed_modules:['data-dashboard']}};
const req={headers:{cookie:'authorization=test-session','x-user-id':'spoofed','x-user-role':'总监'}};
test('central authority validates session and module without trusting user headers',async()=>{let calls=0;const x=await readCentralIdentity(req,'http://authority/api',async(url,options)=>{calls++;assert.equal(url,'http://authority/api/central-auth/me');assert.equal(options.redirect,'manual');assert.equal(options.headers.cookie,req.headers.cookie);assert.equal(options.headers['x-user-id'],undefined);return new Response(JSON.stringify(good));});assert.equal(calls,1);assert.equal(x.userId,'official-user');assert.equal(x.jobTitle,'经理');assert.deepEqual(x.roles,[]);});
test('module removed or departed users are forbidden even with admin permission',async()=>{for(const access of [{allowed_modules:[]},{...good.access,login_blocked:true},{...good.access,master_access:false}]) await assert.rejects(readCentralIdentity(req,'http://authority/api',async()=>new Response(JSON.stringify({...good,access,permissions:{super_admin:true}}))),e=>e.status===403);});
test('no credential, expired session, denied session and outage fail closed',async()=>{await assert.rejects(readCentralIdentity({headers:{}},'http://authority/api',()=>{throw Error('must not fetch');}),e=>e.status===401);for(const [status,expected] of [[401,401],[302,401],[403,403],[500,503]]) await assert.rejects(readCentralIdentity(req,'http://authority/api',async()=>new Response('',{status})),e=>e.status===expected);await assert.rejects(readCentralIdentity(req,'http://authority/api',async()=>{throw Error('offline');}),e=>e.status===503);});
test('malformed successful response does not grant access',async()=>{await assert.rejects(readCentralIdentity(req,'http://authority/api',async()=>new Response('not json')),e=>e.status===503);});

test('highest access only comes from verified central response',async()=>{const x=await readCentralIdentity(req,'http://authority/api',async()=>new Response(JSON.stringify({...good,access:{...good.access,highest_business_access:true}})));assert.equal(x.highestBusinessAccess,true);const y=await readCentralIdentity({...req,headers:{...req.headers,'x-highest-business-access':'true'}},'http://authority/api',async()=>new Response(JSON.stringify(good)));assert.equal(y.highestBusinessAccess,false);});
